"""Sector-specific work samples; completion is a declaration, not a credential."""

BRIEFS = {
    "general": ("Coordina una entrega", "Dos personas necesitan el mismo informe el viernes. Falta confirmar una cifra y tu compañera estará ausente el jueves.", "Un acuerdo con prioridades, responsables y seguimiento", ["Define destinatarios, alcance y fechas que necesitas confirmar.", "Escribe un mensaje que comunique el riesgo y proponga dos alternativas.", "Construye un acuerdo con responsables, plazo y cómo comprobar el cumplimiento."]),
    "technology": ("Diseña y comprueba una solución", "Un equipo necesita registrar solicitudes y consultar su estado. Algunas llegan duplicadas y pueden contener datos personales.", "Una propuesta con casos de prueba y decisiones justificadas", ["Describe usuarios, entradas, salidas y tres criterios de aceptación.", "Propón una solución para duplicados, acceso y errores. Justifica las decisiones.", "Documenta tres pruebas con entrada y resultado esperado, una limitación y cómo mejorarías la solución."]),
    "service": ("Resuelve una reclamación", "Una cliente recibió un cobro duplicado. Está molesta y la devolución depende de otro equipo. El procedimiento permite revisión en dos días hábiles.", "Un registro de atención y una respuesta para la cliente", ["Resume hechos confirmados, información pendiente y la necesidad de la cliente.", "Redacta tu respuesta: reconoce el problema, evita promesas sin autorización y acuerda un plazo.", "Prepara un escalamiento con responsable, seguimiento y criterio para cerrar el caso."]),
    "sales": ("Construye una propuesta consultiva", "Una tienda quiere reducir faltantes de inventario, tiene presupuesto limitado y compara dos proveedores. Tu producto no funciona sin conexión.", "Una propuesta comercial transparente con siguiente paso", ["Plantea cuatro preguntas sobre necesidad, presupuesto y criterios de decisión.", "Escribe una propuesta de valor y responde a la objeción de precio sin ocultar la limitación de conexión.", "Define siguiente paso, fecha de seguimiento y una métrica para evaluar el resultado."]),
    "administration": ("Organiza un expediente", "Recibes tres versiones de un contrato, una solicitud urgente sin firma y un archivo de nómina compartido por error.", "Un índice documental con prioridades y controles de acceso", ["Clasifica los documentos por tipo, versión, responsable y nivel de acceso.", "Propón prioridades y cómo resolverías la firma pendiente y el acceso indebido.", "Escribe una convención de nombres y un registro de cambios para localizar y revisar cada documento."]),
    "finance": ("Explica una conciliación", "El libro ficticio cierra en 1.250.000 COP y el extracto en 1.180.000 COP. Hay un depósito en tránsito de 100.000 COP y una comisión de 30.000 COP sin registrar.", "Un informe de conciliación con soportes pendientes y revisión", ["Compara saldos y calcula qué diferencia explica cada partida. Usa el mismo corte.", "Describe qué soportes solicitarías y qué ajuste tramitarías; distingue tránsito de registro faltante.", "Presenta los saldos conciliados, la explicación numérica y quién revisa o autoriza el ajuste."]),
    "logistics": ("Recupera el control del inventario", "El sistema registra 120 unidades; el conteo encuentra 112. Hay 5 dañadas incluidas en el conteo, una salida de 8 sin registrar y un pedido de 20 para mañana.", "Una hoja de control de diferencias y un plan de despacho", ["Separa existencias físicas, disponibles y registradas. Calcula cada cantidad y la diferencia.", "Decide cómo tratar la salida pendiente y las unidades dañadas, con soportes y responsables.", "Prepara el despacho del pedido y un control para evitar que vuelva a ocurrir la diferencia."]),
    "education": ("Mejora una actividad de aprendizaje", "De 20 participantes ficticios, 12 confunden dos conceptos en la misma actividad. Tres no pueden acceder al video propuesto.", "Una actividad ajustada con criterios y retroalimentación", ["Define un objetivo observable y la evidencia necesaria para comprobarlo.", "Diseña una actividad alternativa accesible y un ejemplo que aborde la confusión.", "Escribe retroalimentación específica y cómo compararás nueva evidencia con el criterio."]),
    "design": ("Convierte un brief en una propuesta", "Una biblioteca invita a jóvenes a un taller gratuito. Necesita una pieza para móvil y un cartel. El texto debe ser legible y las imágenes contar con permiso de uso.", "Un brief y una propuesta con lista de revisión", ["Define objetivo, audiencia, mensaje, canales y entregables del encargo.", "Describe dos propuestas y justifica la elegida por jerarquía, legibilidad y contexto.", "Prepara una revisión de contraste, permisos y formatos; explica cómo validarías la propuesta con la audiencia."]),
    "care": ("Orienta un trámite con confidencialidad", "En una recepción ficticia, alguien pide información de un familiar y otra persona necesita entender un trámite. No tienes autorización para divulgar información clínica ni dar indicaciones médicas.", "Un protocolo de orientación administrativa y protección de datos", ["Distingue qué puedes atender, qué debes verificar y qué información mínima necesitas.", "Redacta una respuesta a la solicitud del familiar y otra que explique el trámite con lenguaje claro.", "Define la derivación al personal competente y cómo registrar la gestión sin exponer datos personales."]),
}


def journey_for(resource):
    title, scenario, outcome, prompts = BRIEFS.get(resource.get("category", "general"), BRIEFS["general"])
    if resource.get("url"):
        scenario = f"Revisa el temario de «{resource['title']}» y trabaja un caso de tu área: {scenario}"
    return {"title": title, "scenario": scenario, "outcome": outcome,
            "steps": [{"id": key, "title": label, "prompt": prompt} for key, label, prompt in zip(
                ["understand", "apply", "demonstrate"], ["Comprende el caso", "Toma decisiones", "Muestra tu resultado"], prompts, strict=True)],
            "criteria": ["Responde al problema planteado", "Justifica decisiones con hechos del caso", "Presenta un resultado que otra persona pueda revisar"],
            "notice": "La práctica publicada es una evidencia declarada. Solo una evaluación independiente aprobada acredita los fundamentos evaluados."}
